PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?total) WHERE {
  {
    SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?p a energia:WellProduction ;
         energia:inConcession ?c ;
         energia:oil ?oil .
    }
    GROUP BY ?c
  }
  {
    SELECT DISTINCT ?s ?c ?pct WHERE {
      ?s a energia:Stake ;
         energia:inConcession ?c ;
         energia:partner ?e ;
         energia:percent ?pct .
      ?e energia:name ?n .
      FILTER(REGEX(?n, "^YPF", "i"))
    }
  }
}
